"""Merge user data from JSON, CSV and Parquet sources with priority resolution."""
import json
import pandas as pd

SOURCES = ["source_a", "source_b", "source_c"]

# Map raw field names -> unified field names
FIELD_MAP = {
    "user_id": "user_id",
    "id": "user_id",
    "userId": "user_id",
    "email": "email",
    "email_address": "email",
    "full_name": "name",
    "name": "name",
    "userName": "name",
    "registration_date": "created_date",
    "created_at": "created_date",
    "joined": "created_date",
    "status": "status",
    "is_active": "status",
    "active": "status",
}


def load_records():
    """Return dict: source_name -> {user_id: {unified_field: value}} preserving row order."""
    out = {}

    # Source A: JSON list of objects
    with open("/data/source_a/users.json") as fh:
        raw_a = json.load(fh)
    out["source_a"] = _normalize(raw_a)

    # Source B: CSV
    df_b = pd.read_csv("/data/source_b/users.csv")
    out["source_b"] = _normalize(df_b.to_dict(orient="records"))

    # Source C: Parquet
    df_c = pd.read_parquet("/data/source_c/users.parquet")
    out["source_c"] = _normalize(df_c.to_dict(orient="records"))

    return out


def _to_date_string(value):
    if value is None or (isinstance(value, float) and pd.isna(value)):
        return None
    ts = pd.to_datetime(value, errors="coerce")
    if pd.isna(ts):
        return str(value)
    return ts.strftime("%Y-%m-%d")


def _missing(value):
    return value is None or (isinstance(value, float) and pd.isna(value)) or (
        isinstance(value, str) and value.strip() == ""
    )


def _normalize(records):
    by_id = {}
    for rec in records:
        mapped = {}
        for raw_key, value in rec.items():
            field = FIELD_MAP.get(raw_key, raw_key)
            if _missing(value):
                continue
            if field == "user_id":
                value = int(value)
            elif field == "created_date":
                value = _to_date_string(value)
            elif field == "status":
                if isinstance(value, bool):
                    value = "active" if value else "inactive"
                value = str(value)
            else:
                value = str(value)
            mapped[field] = value
        if "user_id" not in mapped:
            continue
        by_id[mapped["user_id"]] = mapped
    return by_id


def main():
    data = load_records()

    all_ids = sorted({uid for src in data.values() for uid in src})

    merged_rows = []
    conflicts = []

    for uid in all_ids:
        merged = {"user_id": uid}
        for field in ("name", "email", "created_date", "status"):
            present = {}
            for src in SOURCES:
                if uid in data[src] and field in data[src][uid]:
                    present[src] = data[src][uid][field]

            if not present:
                continue

            selected = None
            for src in SOURCES:  # priority order
                if src in present:
                    selected = present[src]
                    break

            # Conflict: more than one source provides the field with differing values
            if len(present) > 1 and len(set(present.values())) > 1:
                conflicts.append(
                    {
                        "user_id": uid,
                        "field": field,
                        "values": {src: present.get(src) for src in SOURCES if src in present},
                        "selected": selected,
                    }
                )

            merged[field] = selected

        merged_rows.append(merged)

    df = pd.DataFrame(merged_rows, columns=["user_id", "name", "email", "created_date", "status"])
    df["user_id"] = df["user_id"].astype("int64")
    for col in ("name", "email", "created_date", "status"):
        df[col] = df[col].astype("object")

    df.to_parquet("/app/merged_users.parquet", index=False)

    report = {"total_conflicts": len(conflicts), "conflicts": conflicts}
    with open("/app/conflicts.json", "w") as fh:
        json.dump(report, fh, indent=2)

    print(df.to_string())
    print("rows:", len(df), "conflicts:", len(conflicts))


if __name__ == "__main__":
    main()"}

